// margin	

async function adendum_marginList(self, body) {
	const tablename = marginTableName
	const { criteria={}, limit=0, offset=0, columns=[], sort={} } = body
	const searchMap = {
		adendum_id: `adendum_id=try_cast_bigint(\${adendum_id}, 0)`,
	};


	if (Object.keys(sort).length === 0) {
		sort.adendummargin_id = 'asc'
	}


	try {
	
		// hilangkan criteria '' atau null
		for (var cname in criteria) {
			if (criteria[cname]==='' || criteria[cname]===null) {
				delete criteria[cname]
			}
		}

		const args = { db, criteria, tablename }

		// apabila ada keperluan untuk recompose criteria
		if (typeof Extender.marginListCriteria === 'function') {
			// export async function marginListCriteria(self, db, searchMap, criteria, sort, columns, args) {}
			await Extender.marginListCriteria(self, db, searchMap, criteria, sort, columns, args)
		}

		var max_rows = limit==0 ? 10 : limit
		const {whereClause, queryParams} = sqlUtil.createWhereClause(criteria, searchMap) 
		const sql = sqlUtil.createSqlSelect({
			tablename: args.tablename, 
			columns, 
			whereClause, 
			sort: args.sqlSort ?? sort, 
			limit:max_rows+1, 
			offset, 
			queryParams
		})
		const rows = await db.any(sql, queryParams);

		
		var i = 0
		const data = []
		for (var row of rows) {
			i++
			if (i>max_rows) { break }

			// lookup: marginrange_desc dari field marginrange_desc pada table public.marginrange dimana (public.marginrange.marginrange_id = public.adendum.marginrange_id)
			{
				const { marginrange_desc } = await sqlUtil.lookupdb(db, 'public.marginrange', 'marginrange_id', row.marginrange_id)
				row.marginrange_desc = marginrange_desc
			}
			

			// pasang extender di sini
			if (typeof Extender.detilListRow === 'function') {
				// export async function detilListRow(self, row, args) {}
				await Extender.detilListRow(self, row, args)
			}

			data.push(row)
		}

		var nextoffset = null
		if (rows.length>max_rows) {
			nextoffset = offset+max_rows
		}


		const listData = {
			criteria: criteria,
			limit:  max_rows,
			nextoffset: nextoffset,
			data: data
		}

		if (typeof Extender.detilList === 'function') {
			// export async function detilList(self, listData, args) {}
			await Extender.detilList(self, listData, args)
		}

		return listData
	} catch (err) {
		throw err
	}
}

async function adendum_marginOpen(self, body) {
	const tablename = marginTableName

	try {
		const { id } = body 
		const criteria = { adendummargin_id: id }
		const searchMap = { adendummargin_id: `adendummargin_id = \${adendummargin_id}`}
		const {whereClause, queryParams} = sqlUtil.createWhereClause(criteria, searchMap) 
		const sql = sqlUtil.createSqlSelect({
			tablename, 
			columns:[], 
			whereClause, 
			sort:{}, 
			limit:0, 
			offset:0, 
			queryParams
		})
		const data = await db.one(sql, queryParams);
		if (data==null) { 
			throw new Error(`[${tablename}] data dengan id '${id}' tidak ditemukan`) 
		}	


		// lookup: marginrange_desc dari field marginrange_desc pada table public.marginrange dimana (public.marginrange.marginrange_id = public.adendum.marginrange_id)
		{
			const { marginrange_desc } = await sqlUtil.lookupdb(db, 'public.marginrange', 'marginrange_id', data.marginrange_id)
			data.marginrange_desc = marginrange_desc
		}
		

		// lookup data createby
		{
			const { user_fullname } = await sqlUtil.lookupdb(db, 'core.user', 'user_id', data._createby)
			data._createby = user_fullname ?? ''
		}

		// lookup data modifyby
		{
			const { user_fullname } = await sqlUtil.lookupdb(db, 'core.user', 'user_id', data._modifyby)
			data._modifyby = user_fullname ?? ''
		}	


		// pasang extender untuk olah data
		// export async function marginOpen(self, db, data) {}
		if (typeof Extender.marginOpen === 'function') {
			// export async function marginOpen(self, db, data) {}
			await Extender.marginOpen(self, db, data)
		}

		return data
	} catch (err) {
		throw err
	}
}

