			// apabila ada keperluan pengolahan data SEBELUM disimpan
			if (typeof Extender.marginCreating === 'function') {
				// export async function marginCreating(self, tx, data, seqdata, args) {}
				await Extender.marginCreating(self, tx, data, seqdata, args)
			}

